"""
木のアルゴリズム (Tree Algorithms: Diameter, Path, LCA, Subtree Size)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- tree_diameter(n, g): 木の直径 (最長パスの辺数) およびその端点ペア (u, v) を O(V) で求める。
  木の中の任意の点から最遠点 n1 を求め、n1 からの最遠点 n2 を求めると n1-n2 間が直径となる。
- LCA(n, g, root=0): ダブリングを用いた最近共通祖先 (Lowest Common Ancestor)。
  - 前計算: O(V log V)
  - クエリ lca(u, v), dist(u, v): O(log V)
"""

from collections import deque

# https://github.com/ddfkit/acsampl/blob/main/tree.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def tree_diameter(n,g):
    def bfs(s):
        d=[-1]*n;d[s]=0;q=deque([s])
        while q:
            u=q.popleft()
            for v in g[u]:
                if d[v]<0:d[v]=d[u]+1;q.append(v)
        mx=max(d);return mx,d.index(mx)
    _,u=bfs(0);diam,v=bfs(u)
    return diam,u,v

# https://github.com/ddfkit/acsampl/blob/main/tree.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class LCA:
    def __init__(self,n,g,root=0):
        self.k=n.bit_length();self.depth=[-1]*n;self.par=[[-1]*n for _ in range(self.k)]
        self.depth[root]=0;self.par[0][root]=root;q=deque([root])
        while q:
            u=q.popleft()
            for v in g[u]:
                if self.depth[v]<0:
                    self.depth[v]=self.depth[u]+1;self.par[0][v]=u;q.append(v)
        for i in range(self.k-1):
            for v in range(n):self.par[i+1][v]=self.par[i][self.par[i][v]]
    def query(self,u,v):
        if self.depth[u]<self.depth[v]:u,v=v,u
        diff=self.depth[u]-self.depth[v]
        for i in range(self.k):
            if (diff>>i)&1:u=self.par[i][u]
        if u==v:return u
        for i in range(self.k-1,-1,-1):
            if self.par[i][u]!=self.par[i][v]:u=self.par[i][u];v=self.par[i][v]
        return self.par[0][u]
    def dist(self,u,v):return self.depth[u]+self.depth[v]-2*self.depth[self.query(u,v)]

if __name__ == "__main__":
    # --- 木の直径 ---
    # 0 - 1 - 2 - 3
    #     |
    #     4
    # 任意の点 (0) から最遠点 u を求め、u から最遠点 v を求めると u-v が直径
    g = [[1], [0, 2, 4], [1, 3], [2], [1]]
    diam, u, v = tree_diameter(5, g)
    assert diam == 3 and {u, v} in [{0, 3}, {4, 3}, {3, 0}, {3, 4}]

    # --- 最近共通祖先 (LCA) ---
    lca = LCA(5, g, 0)
    assert lca.query(3, 4) == 1
    assert lca.dist(3, 4) == 3
    assert lca.dist(0, 3) == 3
    print("tree.py: all tests passed!")
